'use strict';
// Only the presentation changes coordinates. Combat and room snapshots keep world units.
const heroSprites=new Image(),worldSprites=new Image();
heroSprites.src='assets/heroes-sprites.webp';worldSprites.src='assets/world-sprites.webp';
const camera={x:750,y:500,follow:true,ready:false,lastTime:-1,hero:null};
let skillAim=null,attackPointer=null,forestPattern=null;
const originalChooseHero=chooseHero;
chooseHero=function(id){originalChooseHero(id);const i=HEROES.findIndex(h=>h.id===selected.id);$('heroFigure').style.backgroundPosition=`${i%3*50}% ${Math.floor(i/3)*100}%`;$('heroFigure').setAttribute('aria-label',selected.name);$('selectedName').textContent=selected.name;$('selectedRole').textContent=selected.role;$('selectedDetails').textContent=selected.details;};
chooseHero(selected.id);
function projectPoint(p){return {x:view.x+p.x*view.scale,y:view.y+p.y*view.scale*(view.tilt||1)};}
function setBattleCamera(){view.tilt=.65;if(game&&camera.follow){const p=game.player;if(!camera.ready||game.time<camera.lastTime||camera.hero!==p.id){camera.x=p.x;camera.y=p.y;camera.ready=true;camera.hero=p.id;}camera.x+=(p.x-camera.x)*.14;camera.y+=(p.y-camera.y)*.14;camera.lastTime=game.time;view.scale=Math.max(.65,Math.min(1.3,view.height/510));view.x=view.width*.48-camera.x*view.scale;view.y=view.height*.57-camera.y*view.scale*view.tilt;}else{view.scale=Math.min(view.width/WIDTH,view.height/(HEIGHT*view.tilt));view.x=(view.width-WIDTH*view.scale)/2;view.y=(view.height-HEIGHT*view.scale*view.tilt)/2;camera.ready=false;}}
draw=function(){if(!view.width||!view.height)return;setBattleCamera();ctx.save();ctx.clearRect(0,0,view.width,view.height);ctx.fillStyle='#132d28';ctx.fillRect(0,0,view.width,view.height);ctx.translate(view.x,view.y);ctx.scale(view.scale,view.scale*view.tilt);
  // Pad the world with trees at their original scale; the playable map keeps its own bounds.
  if(terrain.complete&&terrain.naturalWidth){if(!forestPattern){const tile=document.createElement('canvas');tile.width=360;tile.height=200;const tc=tile.getContext('2d');for(let row=0;row<2;row++)for(let col=0;col<2;col++){tc.save();tc.translate(col?360:0,row?200:0);tc.scale(col?-1:1,row?-1:1);tc.drawImage(terrain,terrain.naturalWidth*.55,0,terrain.naturalWidth*.12,terrain.naturalHeight*.1,0,0,180,100);tc.restore();}forestPattern=ctx.createPattern(tile,'repeat');}ctx.fillStyle=forestPattern;ctx.fillRect(-WIDTH,-HEIGHT,WIDTH*3,HEIGHT*3);ctx.fillStyle='#04121b38';ctx.fillRect(-WIDTH,-HEIGHT,WIDTH*3,HEIGHT*3);}
  ground();ctx.restore();if(game){renderBattle();renderMini();}};
function groundRing(p,r,color,fill=false){const s=projectPoint(p);ctx.beginPath();ctx.ellipse(s.x,s.y,r*view.scale,r*view.scale*view.tilt,0,0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=1.5;if(fill){ctx.fillStyle=color.slice(0,7)+'15';ctx.fill();}ctx.stroke();}
function atlasSprite(image,index,point,size,flip=false,bob=0){if(!image.complete||!image.naturalWidth)return false;const cell=image.naturalWidth/3,s=size*view.scale;ctx.save();ctx.translate(point.x,point.y+bob);if(flip)ctx.scale(-1,1);ctx.drawImage(image,index%3*cell,Math.floor(index/3)*cell,cell,cell,-s/2,-s*.91,s,s);ctx.restore();return true;}
renderBattle=function(){const p=game.player;if(!p.dead){groundRing(p,p.range,p.team===0?'#60e4db40':'#ff916840');if(p.destination)groundRing(p.destination,12,'#d5fff0');if(skillAim){if(skillAim.action==='w'){const from=projectPoint(p),to=projectPoint(skillAim.aim);ctx.strokeStyle='#bdfff0';ctx.lineWidth=12;ctx.globalAlpha=.4;ctx.beginPath();ctx.moveTo(from.x,from.y);ctx.lineTo(to.x,to.y);ctx.stroke();ctx.globalAlpha=1;groundRing(skillAim.aim,20,'#bdfff0');}else groundRing(p,skillAim.action==='q'?170:300,'#bdfff0',true);}}
  for(const e of [...game.entities].sort((a,b)=>a.y-b.y)){const at=projectPoint(e);if(e.dead){if(e.player){ctx.fillStyle='#e3faff';ctx.textAlign='center';ctx.font='16px "Noto Sans Thai"';ctx.fillText('เกิดใหม่ '+Math.ceil(e.respawn)+' วิ',at.x,at.y-15);}continue;}
    const ally=e.team===p.team,color=e.team===2?PURPLE:ally?BLUE:RED;let size,index,img;
    if(e.type==='hero'){size=e.player?116:104;index=Math.max(0,HEROES.findIndex(h=>h.id===e.def.id));img=heroSprites;}else if(e.type==='minion'){size=49;index=0;img=heroSprites;}else{img=worldSprites;size=e.type==='base'?226:e.type==='tower'?178:e.camp==='boss'?185:116;index=e.type==='tower'?(e.team===0?0:1):e.type==='base'?(e.team===0?2:3):e.camp==='boss'?5:4;}
    if(at.x<-size||at.y<-size||at.x>view.width+size||at.y>view.height+size)continue;
    if(e.type==='tower'&&distance(e,p)<e.range+100)groundRing(e,e.range,color+'30');
    ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(at.x,at.y,e.radius*view.scale*1.15,e.radius*view.scale*.5,0,0,Math.PI*2);ctx.fill();
    groundRing(e,e.radius+3,e.player?'#f0fff5':color+'90');if(e.shield>0)groundRing(e,e.radius+11,'#b0e7ff');if(e.buff>0||e.rage>0||e.spirit>0)groundRing(e,e.radius+17,e.rage>0?'#f1d67b':PURPLE);
    const moved=e.drawX!==undefined&&Math.hypot(e.x-e.drawX,e.y-e.drawY)>.03;if(moved&&Math.abs(e.x-e.drawX)>.02)e.drawFlip=e.x<e.drawX;e.drawX=e.x;e.drawY=e.y;
    const bob=moved&&['hero','minion'].includes(e.type)?Math.sin(game.time*16+e.id)*2:0;
    if(!atlasSprite(img,index,at,size,e.drawFlip,bob)){ctx.fillStyle=color;ctx.beginPath();ctx.arc(at.x,at.y-12,e.radius*view.scale,0,Math.PI*2);ctx.fill();}
    const barWidth=(e.type==='minion'?28:e.type==='base'?92:e.type==='tower'?72:62)*Math.max(.85,view.scale),barY=at.y-size*view.scale*.79;
    ctx.fillStyle='#030b0dd9';ctx.fillRect(at.x-barWidth/2-1,barY-1,barWidth+2,7);ctx.fillStyle=color;ctx.fillRect(at.x-barWidth/2,barY,barWidth*Math.max(0,e.hp/e.maxHp),5);
    if(e.type==='hero'){ctx.fillStyle=e.player?'#ffffff':ally?'#c0f6e6':'#ffc4a8';ctx.font='11px "Noto Sans Thai", sans-serif';ctx.textAlign='center';ctx.shadowColor='#000';ctx.shadowBlur=3;ctx.fillText((e.player?'คุณ':e.clientName||'')+'  '+e.level,at.x,barY-5);ctx.shadowBlur=0;if(e.stun>0){ctx.fillStyle='#ffe07e';ctx.fillText('✧ สตัน',at.x,barY-21);}if(e.recall>0){groundRing(e,38,'#72ffff');ctx.fillStyle='#b4ffff';ctx.fillText('กลับฐาน '+e.recall.toFixed(1),at.x,at.y+23);}}
    if(e.type==='base'){ctx.fillStyle=color;ctx.textAlign='center';ctx.font='11px "Noto Sans Thai"';ctx.fillText(baseOpen(e.team)?'ฐานเปิด':'ฐานมีเกราะ',at.x,at.y+20);}
  }
  for(const f of effects){ctx.globalAlpha=Math.max(0,f.life/f.max);const from=projectPoint(f);if(f.type==='ring')groundRing(f,f.radius*(1-f.life/f.max*.25),f.color,true);if(f.type==='shot'){const to=projectPoint({x:f.tx,y:f.ty});ctx.strokeStyle=f.color;ctx.shadowColor=f.color;ctx.shadowBlur=9;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(from.x,from.y-30*view.scale);ctx.lineTo(to.x,to.y-30*view.scale);ctx.stroke();ctx.shadowBlur=0;}if(f.type==='text'){ctx.fillStyle=f.color;ctx.font='bold 17px "Chakra Petch"';ctx.textAlign='center';ctx.fillText(f.text,from.x,from.y-56*view.scale-(1-f.life/f.max)*30);}ctx.globalAlpha=1;}
};
renderMini=function(){const w=view.height<450?125:154,h=w*HEIGHT/WIDTH,x=14,y=14,s=w/WIDTH;ctx.fillStyle='#061710ed';ctx.fillRect(x-3,y-3,w+6,h+6);if(terrain.complete&&terrain.naturalWidth)ctx.drawImage(terrain,x,y,w,h);ctx.fillStyle='#02131c66';ctx.fillRect(x,y,w,h);for(const route of ROUTES){ctx.beginPath();route.forEach((point,i)=>i?ctx.lineTo(x+point[0]*s,y+point[1]*s):ctx.moveTo(x+point[0]*s,y+point[1]*s));ctx.strokeStyle='#c3ddc377';ctx.lineWidth=1;ctx.stroke();}for(const e of game.entities){if(e.dead||e.type==='minion'||!visibleToTeam(e,game.player.team))continue;ctx.fillStyle=e.player?'#fff':e.team===game.player.team?BLUE:e.team===2?PURPLE:RED;ctx.beginPath();ctx.arc(x+e.x*s,y+e.y*s,e.player?4:e.type==='hero'?2.8:2,0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#ceeee599';ctx.strokeRect(x,y,w,h);const left=Math.max(0,-view.x/view.scale),top=Math.max(0,-view.y/(view.scale*view.tilt));ctx.strokeStyle='#fff9';ctx.strokeRect(x+left*s,y+top*s,Math.max(0,Math.min(WIDTH-left,view.width/view.scale))*s,Math.max(0,Math.min(HEIGHT-top,view.height/(view.scale*view.tilt)))*s);};
$('cameraBtn').onclick=()=>{camera.follow=!camera.follow;$('cameraBtn').textContent=camera.follow?'กล้อง: ตามฮีโร่':'กล้อง: ทั้งสนาม';};
$('shopClose').onclick=()=>$('shopBtn').onclick();
$('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else{await document.documentElement.requestFullscreen();try{await screen.orientation.lock('landscape');}catch{}}}catch{notify('เบราว์เซอร์นี้ไม่รองรับเต็มจอ · หมุนมือถือแนวนอนเพื่อเล่น');}};
$('portraitContinue').onclick=()=>document.body.classList.add('portrait-ok');
function controlsBlocked(){return !game||game.paused||game.finished||game.player.dead||net.localPause||$('help').open||$('scoreboard').open||document.body.classList.contains('shop-open');}
function releaseAttack(){attackPointer=null;keys.delete(' ');}
for(const button of document.querySelectorAll('[data-action]')){const action=button.dataset.action;if(action==='attack'){button.onclick=null;button.onpointerdown=e=>{if(controlsBlocked())return;e.preventDefault();attackPointer=e.pointerId;button.setPointerCapture(e.pointerId);keys.add(' ');attackPlayer();};button.onpointerup=button.onpointercancel=button.onlostpointercapture=releaseAttack;}
  else if(['q','w','e'].includes(action)){button.onclick=e=>{if(e.detail===0&&!controlsBlocked())useSkill(action);};button.onpointerdown=e=>{if(skillAim||controlsBlocked()||game.player.cd[action]>0)return;e.preventDefault();button.setPointerCapture(e.pointerId);skillAim={id:e.pointerId,action,origin:{x:e.clientX,y:e.clientY},aim:{...pointer},dragged:false};if(action!=='w')skillAim.aim={x:game.player.x,y:game.player.y};};button.onpointermove=e=>{if(!skillAim||e.pointerId!==skillAim.id||action!=='w')return;const dx=e.clientX-skillAim.origin.x,dy=e.clientY-skillAim.origin.y,d=Math.hypot(dx,dy);if(d>9){skillAim.dragged=true;skillAim.aim={x:game.player.x+dx/d*210,y:game.player.y+dy/d*210/view.tilt,manual:true};pointer=skillAim.aim;}};button.onpointerup=e=>{if(!skillAim||e.pointerId!==skillAim.id)return;const aim=skillAim;skillAim=null;if(!controlsBlocked()){pointer=aim.aim;useSkill(action,null,aim.aim);}};button.onpointercancel=button.onlostpointercapture=()=>{skillAim=null;};}
}
window.addEventListener('blur',()=>{releaseAttack();skillAim=null;});
document.addEventListener('visibilitychange',()=>{if(document.hidden){releaseAttack();skillAim=null;}});
// Prevent the map overlay from issuing a walk command under its UI on either client.
canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),w=view.height<450?125:154;if(e.clientX-r.left<14+w&&e.clientY-r.top<14+w*HEIGHT/WIDTH){e.stopImmediatePropagation();}},true);
resize();
